{
  "book_code": "JASHER",
  "verses": [
    {
      "chapter": 2,
      "verse": 25,
      "source_ref": "2:25",
      "text_ar": "وحملت مرة أخرى وأنجبت ابنة، فأسمتها ناما، لأنها قالت: بعد أن ذبلت حصلت على المتعة والسرور."
    },
    {
      "chapter": 2,
      "verse": 26,
      "source_ref": "2:26",
      "text_ar": "وكان لاميك قد شاخ وتقدم في السن، وكانت عينيه ضعيفتين لا يرى بهما، وكان طوبال كاين، ابنه، يقوده، وفي يومٍ واحدٍ ذهب لاميك إلى الحقل وكان طوبال كاين ابنه معه، وبينما كانا يمشيان في الحقل اقترب منهما قايين ابن آدم؛ لأن لاميك كان كبيراً في السن ولا يرى كثيراً، وكان طوبال كاين ابنه صغيراً جداً."
    },
    {
      "chapter": 2,
      "verse": 27,
      "source_ref": "2:27",
      "text_ar": "فأخبر طوبال كاين والده أن يشد قوسه، وبالسهام ضرب قايين الذي كان لا يزال بعيداً، وقتله، لأنه بدا لهم كحيوان."
    },
    {
      "chapter": 2,
      "verse": 28,
      "source_ref": "2:28",
      "text_ar": "وَدَخَلَتِ السهامُ جسد قايين رغم بُعده عنهم، فَسَقَطَ على الأرض ومات."
    },
    {
      "chapter": 2,
      "verse": 29,
      "source_ref": "2:29",
      "text_ar": "وأجَابَ الرَّبُّ قايين بالشر وفقاً لشره الذي ارتكبه على أخيه هابيل، بحسب كلمة الرب التي كان قد نطق بها."
    },
    {
      "chapter": 2,
      "verse": 30,
      "source_ref": "2:30",
      "text_ar": "وعندما مات قايين، ذهب لاميك وطوبال ليروا الحيوان الذي قتلوا، فرأوا، فإليك قايين جدهم سقط ميتاً على الأرض."
    },
    {
      "chapter": 2,
      "verse": 31,
      "source_ref": "2:31",
      "text_ar": "فحزن لاميك كثيراً لما فعله، وبصفق يديه ضرب ابنه فتسبب في موته."
    },
    {
      "chapter": 2,
      "verse": 32,
      "source_ref": "2:32",
      "text_ar": "وسمعت زوجات لاميك ما فعله، فطلبن قتلَه."
    },
    {
      "chapter": 2,
      "verse": 33,
      "source_ref": "2:33",
      "text_ar": "وبدأت زوجات لاميك يكرهنه من ذلك اليوم، لأنه قتل قايين وطوبال كاين، فابتعدن عنه ولم يكن يلتفتن له في تلك الأيام."
    },
    {
      "chapter": 2,
      "verse": 34,
      "source_ref": "2:34",
      "text_ar": "فجاء لاميك إلى زوجاته، وضغط عليهن ليستمعن إليه فيما يخص هذا الأمر."
    }
  ]
}
